以下为具体的业务配置

server {
    listen 443 ssl;
    listen 443 quic reuseport;
    listen [::]:443 ssl;
    listen [::]:443 quic reuseport;

    http2 on;

    #仅允许cfip访问
    include cf-ips.conf;
    deny all;

    server_name $配置自己的域名;

    ssl_certificate $配置自己的证书;
    ssl_certificate_key $配置自己的证书;

    ssl_protocols TLSv1.3;
    ssl_ecdh_curve X25519:prime256v1:secp384r1;
    ssl_prefer_server_ciphers off;

    index index.html;
    root /var/www/html;
    error_page 404 /404.html;

    # HTTP3
    add_header Alt-Svc 'h3=":443"; ma=86400';
    # HSTS
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
}

限制只允许 cdn 地址

必须写入 nginx 的根目录, 否则上方配置 include 需使用绝对路径

#!/bin/bash

# 配置
CF_IP_FILE="/etc/nginx/cf-ips.conf"   # 输出文件
TMP_FILE="/tmp/cf-ips.tmp"

# Cloudflare 官方 IP 列表
CF_IPV4_URL="https://www.cloudflare.com/ips-v4"
CF_IPV6_URL="https://www.cloudflare.com/ips-v6"

# 写入文件头
echo "# Generated by cf-ips-update.sh on $(date)" > "$TMP_FILE"

# 下载 IPv4 + IPv6
for url in "$CF_IPV4_URL" "$CF_IPV6_URL"; do
    curl -sf "$url" | while read ip || [ -n "$ip" ]; do
        echo "allow $ip;" >> "$TMP_FILE"
    done
done

# 替换旧文件
mv "$TMP_FILE" "$CF_IP_FILE"
chmod 644 "$CF_IP_FILE"

nginx -t && nginx -s reload

echo "Cloudflare IP list updated: $CF_IP_FILE"

